function parseMoney(v){if(v===null||v===undefined||v==='')return 0;if(typeof v==='number')return Number.isFinite(v)?v:0;let s=String(v).replace(/[^\d,.-]/g,'');if(!s)return 0;if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');return Number(s)||0}
function moeda(v){if(v===null||v===undefined||v==='')return '';return parseMoney(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}
function moedaChange(valor,setter){const digits=String(valor||'').replace(/\D/g,'');setter(digits?(Number(digits)/100).toFixed(2):'')}
function emptyResultadosProcesso(){return {primeira:'',segunda:[]}}
function limparObservacoesProcesso(obs=''){return String(obs||'').replace(/\n?\[PERICIAS_PROCESSO:[^\]]*\]/g,'').replace(/\n?\[RESULTADOS_PROCESSO:[^\]]*\]/g,'').trim()}
function normalizarResultadoPrimeira(v=''){const s=String(v||'');if(RESULTADOS_PRIMEIRA.some(([k])=>k===s))return s;const low=s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return RESULTADOS_PRIMEIRA.find(([,l])=>l.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()===low)?.[0]||''}
function extrairPericiasProcesso(p={}){const m=String(p?.observacoes||'').match(/\[PERICIAS_PROCESSO:([^\]]*)\]/);if(!m)return [];try{return (JSON.parse(decodeURIComponent(m[1]))||[]).filter(v=>PERICIAS_OPCOES.some(([k])=>k===v))}catch{return []}}
function extrairResultadosProcesso(p={}){const m=String(p?.observacoes||'').match(/\[RESULTADOS_PROCESSO:([^\]]*)\]/);if(!m)return {...emptyResultadosProcesso(),primeira:normalizarResultadoPrimeira(p?.resultado)};try{const r=JSON.parse(decodeURIComponent(m[1]))||{};return {primeira:normalizarResultadoPrimeira(r.primeira||p?.resultado),segunda:Array.isArray(r.segunda)?r.segunda.filter(v=>RESULTADOS_SEGUNDA.some(([k])=>k===v)):[]}}catch{return {...emptyResultadosProcesso(),primeira:normalizarResultadoPrimeira(p?.resultado)}}}
function juntarMetadadosProcesso(obs='',pericias=[],resultados={}){const limpas=limparObservacoesProcesso(obs);const ps=(pericias||[]).filter(v=>PERICIAS_OPCOES.some(([k])=>k===v));const rs={primeira:normalizarResultadoPrimeira(resultados.primeira),segunda:(resultados.segunda||[]).filter(v=>RESULTADOS_SEGUNDA.some(([k])=>k===v))};const marcadorPericias=ps.length?`${PERICIAS_PROCESSO_MARK}${encodeURIComponent(JSON.stringify(ps))}]`:'';const marcadorResultados=(rs.primeira||rs.segunda.length)?`${RESULTADOS_PROCESSO_MARK}${encodeURIComponent(JSON.stringify(rs))}]`:'';return [limpas,marcadorPericias,marcadorResultados].filter(Boolean).join('\n')}
function emptyReclamada(){return {parte_contraria_id:'',parte_contraria:'',nova_parte_nome:'',nova_parte_cnpj:'',nova_parte_grupo:''}}
function normalizarNomeReclamada(v){return String(v||'').trim()}
function nomesPartesContrariasJson(p={}){if(!Array.isArray(p?.partes_contrarias))return [];return p.partes_contrarias.map(r=>normalizarNomeReclamada(r?.nome||r?.parte_contraria)).filter(Boolean)}
function nomesReclamadasProcesso(p={}){const fromJson=nomesPartesContrariasJson(p);if(fromJson.length)return fromJson;const texto=normalizarNomeReclamada(p?.parte_contraria);if(!texto)return [];return texto.split(/\s+\|\s+|;\s*/).map(normalizarNomeReclamada).filter(Boolean)}
function reclamadasFromProcesso(p={},fallback=null){
  const rows=Array.isArray(p?.partes_contrarias)?p.partes_contrarias.map(r=>({parte_contraria_id:String(r?.id||r?.parte_contraria_id||''),parte_contraria:normalizarNomeReclamada(r?.nome||r?.parte_contraria),nova_parte_nome:'',nova_parte_cnpj:'',nova_parte_grupo:''})).filter(r=>r.parte_contraria_id||r.parte_contraria):[]
  if(rows.length)return rows
  const nomes=nomesReclamadasProcesso(p)
  if(nomes.length)return nomes.map((nome,i)=>({parte_contraria_id:i===0?String(p?.parte_contraria_id||''):'',parte_contraria:nome,nova_parte_nome:'',nova_parte_cnpj:'',nova_parte_grupo:''}))
  if(fallback?.id||fallback?.nome)return [{parte_contraria_id:String(fallback?.id||''),parte_contraria:normalizarNomeReclamada(fallback?.nome),nova_parte_nome:'',nova_parte_cnpj:'',nova_parte_grupo:''}]
  return [emptyReclamada()]
}
function reclamadasDoForm(form={}){return Array.isArray(form.reclamadas)&&form.reclamadas.length?form.reclamadas:reclamadasFromProcesso(form)}
function resumoReclamadas(rows=[]){return rows.map(r=>normalizarNomeReclamada(r.parte_contraria||r.nova_parte_nome)).filter(Boolean).join(' | ')}
function processoTemReclamada(p={},nome=''){const alvo=normalizarNomeReclamada(nome).toLowerCase();return !!alvo&&nomesReclamadasProcesso(p).some(n=>n.toLowerCase()===alvo)}
function ordinalReclamada(i){return `${i}\u00aa RECLAMADA`}
function ReclamadasProcessoFields({form,setForm,partes=[]}){
  const rows=reclamadasDoForm(form)
  const commit=(nextRows)=>setForm(f=>({...f,reclamadas:nextRows,parte_contraria_id:nextRows[0]?.parte_contraria_id||'',parte_contraria:resumoReclamadas(nextRows)}))
  const updateRow=(index,patch)=>commit(rows.map((row,i)=>i===index?{...row,...patch}:row))
  const addRow=()=>commit([...rows,emptyReclamada()])
  const removeRow=(index)=>commit(rows.filter((_,i)=>i!==index))
  return <div style={{marginBottom:4}}>
    {rows.map((row,index)=><div key={index}>
      <div style={{display:'grid',gridTemplateColumns:'minmax(220px,1fr) auto',gap:8,alignItems:'end'}}>
        <F label={rows.length>1?ordinalReclamada(index+1):'Parte contr\u00e1ria / reclamada'}>
          <select style={INP} value={row.parte_contraria_id||''} onChange={e=>{const v=e.target.value;const parte=partes.find(x=>x.id===v);updateRow(index,{parte_contraria_id:v,parte_contraria:v==='__novo__'?(row.nova_parte_nome||''):(parte?.nome||''),nova_parte_nome:v==='__novo__'?row.nova_parte_nome||'':'',nova_parte_cnpj:v==='__novo__'?row.nova_parte_cnpj||'':'',nova_parte_grupo:v==='__novo__'?row.nova_parte_grupo||'':''})}}>
            <option value="">Selecione</option>
            {partes.map(p=><option key={p.id} value={p.id}>{p.nome}</option>)}
            <option value="__novo__">Outro / cadastrar nova parte...</option>
          </select>
        </F>
        <div style={{display:'flex',gap:6,marginBottom:12}}>
          {index===rows.length-1&&<button type="button" title="Adicionar reclamada" onClick={addRow} style={{height:42,width:42,border:'1px solid '+C.blue,background:C.white,color:C.blue,borderRadius:8,fontWeight:900,cursor:'pointer',display:'inline-flex',alignItems:'center',justifyContent:'center'}}><Plus size={18}/></button>}
          {rows.length>1&&<button type="button" title="Remover reclamada" onClick={()=>removeRow(index)} style={{height:42,width:42,border:'1px solid '+C.border,background:C.white,color:C.muted,borderRadius:8,fontWeight:900,cursor:'pointer',display:'inline-flex',alignItems:'center',justifyContent:'center'}}><X size={16}/></button>}
        </div>
      </div>
      {row.parte_contraria_id==='__novo__'&&<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(180px,1fr))',gap:12,background:C.grayBg,border:'1px solid '+C.border,borderRadius:12,padding:12,marginBottom:12}}>
        <F label="Nome da nova parte"><input style={INP} value={row.nova_parte_nome||''} onChange={e=>updateRow(index,{nova_parte_nome:e.target.value,parte_contraria:e.target.value})} placeholder="Raz\u00e3o social"/></F>
        <F label="CNPJ"><input style={INP} value={row.nova_parte_cnpj||''} onChange={e=>updateRow(index,{nova_parte_cnpj:e.target.value})}/></F>
        <F label="Grupo econ\u00f4mico"><input style={INP} value={row.nova_parte_grupo||''} onChange={e=>updateRow(index,{nova_parte_grupo:e.target.value})}/></F>
      </div>}
    </div>)}
  </div>
}
function toggleSegundaInstancia(arr=[],key){let next=Array.isArray(arr)?[...arr]:[];if(next.includes(key))return next.filter(x=>x!==key);if(key==='mantida_primeiro_grau')return [key];next=next.filter(x=>x!=='mantida_primeiro_grau');if(key==='reclamante_total')next=next.filter(x=>x!=='reclamante_parcial');if(key==='reclamante_parcial')next=next.filter(x=>x!=='reclamante_total');if(key==='reclamada_total')next=next.filter(x=>x!=='reclamada_parcial');if(key==='reclamada_parcial')next=next.filter(x=>x!=='reclamada_total');return [...next,key]}
function limparObservacoesParcelas(obs=''){return String(obs||'').replace(/\n?\[VENCIMENTOS_PARCELAS:[^\]]*\]/g,'').replace(/\n?\[VALORES_PARCELAS:[^\]]*\]/g,'').replace(/\n?\[DIVIDIR_PARCELAS:[^\]]*\]/g,'').replace(/\n?\[PAGAMENTOS_CAMPOS:[^\]]*\]/g,'').replace(/\n?\[AUDITORIA_PAGAMENTOS:[^\]]*\]/g,'').replace(/\n?\[REGISTRO_FINANCEIRO_EXCLUIDO:[^\]]*\]/g,'').replace(/\n?\[APOLICE_FORMA:[^\]]*\]/g,'').replace(/\n?\[APOLICE_PARCELAS:[^\]]*\]/g,'').replace(/\n?\[APOLICE_VENCIMENTOS:[^\]]*\]/g,'').replace(/\n?\[APOLICE_VALORES:[^\]]*\]/g,'').replace(/\n?\[APOLICE_DIVIDIR:[^\]]*\]/g,'').trim()}
function extrairVencimentosParcelas(obj={}){const obs=String(obj?.observacoes||'');const m=obs.match(/\[VENCIMENTOS_PARCELAS:([^\]]*)\]/);const arr=m?m[1].split(',').map(x=>x.trim()).filter(Boolean):[];if(!arr.length&&obj?.primeiro_vencimento)arr.push(obj.primeiro_vencimento);const n=Math.max(1,Number(obj?.numero_parcelas||1));while(arr.length<n)arr.push('');return arr.slice(0,n)}
function extrairDividirParcelas(obj={}){const obs=String(obj?.observacoes||'');const m=obs.match(/\[DIVIDIR_PARCELAS:([^\]]*)\]/);return m?m[1]!=='nao':true}
function extrairValoresParcelas(obj={}){const obs=String(obj?.observacoes||'');const m=obs.match(/\[VALORES_PARCELAS:([^\]]*)\]/);const n=Math.max(1,Number(obj?.numero_parcelas||1));const arr=m?m[1].split(',').map(x=>parseMoney(x)):[];const valorPrincipal=parseMoney(obj.valor_bruto);const total=valorPrincipal>0?valorPrincipal:totalFinanceiroBrutoRegistro(obj);if(!arr.length){const igual=total/n;for(let i=0;i<n;i++)arr.push(igual)}while(arr.length<n)arr.push(0);return arr.slice(0,n)}
function juntarObservacoesParcelas(obs='',vencimentos=[],valores=[],dividir=true){const limpas=limparObservacoesParcelas(obs);const datas=(vencimentos||[]).map(x=>String(x||'').trim()).filter(Boolean);const marcadorDatas=datas.length?`${VENC_MARK}${datas.join(',')}]`:'';const marcadorDividir=`${DIVIDIR_MARK}${dividir?'sim':'nao'}]`;const marcadorValores=!dividir&&valores?.length?`${VALORES_MARK}${valores.map(v=>parseMoney(v).toFixed(2)).join(',')}]`:'';return [limpas,marcadorDatas,marcadorDividir,marcadorValores].filter(Boolean).join('\n')}
function extrairPagamentosCampos(obj={}){const obs=String(obj?.observacoes||'');const m=obs.match(/\[PAGAMENTOS_CAMPOS:([^\]]*)\]/);if(!m)return {};try{return JSON.parse(decodeURIComponent(m[1]))||{}}catch{return {}}}
function juntarPagamentosCampos(obs='',pagos={}){const limpas=String(obs||'').replace(/\n?\[PAGAMENTOS_CAMPOS:[^\]]*\]/g,'').replace(/\n?\[AUDITORIA_PAGAMENTOS:[^\]]*\]/g,'').replace(/\n?\[REGISTRO_FINANCEIRO_EXCLUIDO:[^\]]*\]/g,'').trim();const marcador=pagos&&Object.keys(pagos).length?`${PAGO_MARK}${encodeURIComponent(JSON.stringify(pagos))}]`:'';return [limpas,marcador].filter(Boolean).join('\n')}
function extrairAuditoriaPagamentos(obj={}){const obs=String(obj?.observacoes||'');const m=obs.match(/\[AUDITORIA_PAGAMENTOS:([^\]]*)\]/);if(!m)return [];try{return JSON.parse(decodeURIComponent(m[1]))||[]}catch{return []}}
function juntarAuditoriaPagamentos(obs='',auditoria=[]){const limpas=String(obs||'').replace(/\n?\[AUDITORIA_PAGAMENTOS:[^\]]*\]/g,'').trim();const marcador=auditoria?.length?`${AUDIT_PAGO_MARK}${encodeURIComponent(JSON.stringify(auditoria))}]`:'';return [limpas,marcador].filter(Boolean).join('\n')}
const EXCLUIDO_MARK='[REGISTRO_FINANCEIRO_EXCLUIDO:'
function usuarioAuditoria(profile){return {usuario_id:profile?.id||'',usuario_nome:profile?.nome||profile?.email||profile?.id||'',data:new Date().toISOString()}}
function extrairRegistroExcluido(obj={}){const obs=String(obj?.observacoes||'');const m=obs.match(/\[REGISTRO_FINANCEIRO_EXCLUIDO:([^\]]*)\]/);if(!m)return null;try{return JSON.parse(decodeURIComponent(m[1]))||null}catch{return null}}
function financeiroExcluido(f={}){return !!extrairRegistroExcluido(f)}
function temPagamentoCampoAtivo(f={}){return Object.values(extrairPagamentosCampos(f)||{}).some(v=>v?.pago)}
function juntarRegistroExcluido(obs='',evento=null){const limpas=String(obs||'').replace(/\n?\[REGISTRO_FINANCEIRO_EXCLUIDO:[^\]]*\]/g,'').trim();const marcador=evento?`${EXCLUIDO_MARK}${encodeURIComponent(JSON.stringify(evento))}]`:'';return [limpas,marcador].filter(Boolean).join('\n')}
function limparApoliceObs(obs=''){return String(obs||'').replace(/\n?\[APOLICE_FORMA:[^\]]*\]/g,'').replace(/\n?\[APOLICE_PARCELAS:[^\]]*\]/g,'').replace(/\n?\[APOLICE_VENCIMENTOS:[^\]]*\]/g,'').replace(/\n?\[APOLICE_VALORES:[^\]]*\]/g,'').replace(/\n?\[APOLICE_DIVIDIR:[^\]]*\]/g,'').trim()}
function extrairApoliceForma(obj={}){const obs=String(obj?.observacoes||'');const m=obs.match(/\[APOLICE_FORMA:([^\]]*)\]/);return m?m[1]:'avista'}
function extrairApoliceParcelas(obj={}){const obs=String(obj?.observacoes||'');const m=obs.match(/\[APOLICE_PARCELAS:([^\]]*)\]/);return m?Math.max(1,Number(m[1])||1):1}
function extrairApoliceVencimentos(obj={}){const obs=String(obj?.observacoes||'');const m=obs.match(/\[APOLICE_VENCIMENTOS:([^\]]*)\]/);const arr=m?m[1].split(',').map(x=>x.trim()).filter(Boolean):[];const n=extrairApoliceParcelas(obj);while(arr.length<n)arr.push('');return arr.slice(0,n)}
function extrairApoilceDividir(obj={}){const obs=String(obj?.observacoes||'');const m=obs.match(/\[APOLICE_DIVIDIR:([^\]]*)\]/);return m?m[1]!=='nao':true}
function extrairApoliceValores(obj={}){const obs=String(obj?.observacoes||'');const m=obs.match(/\[APOLICE_VALORES:([^\]]*)\]/);const n=extrairApoliceParcelas(obj);const arr=m?m[1].split(',').map(x=>parseMoney(x)):[];const total=parseMoney(obj.seguro_premio);if(!arr.length){const igual=n>0?total/n:0;for(let i=0;i<n;i++)arr.push(igual)}while(arr.length<n)arr.push(0);return arr.slice(0,n)}
function juntarApoliceParcelamento(obs='',forma,vencs,valores,dividir){const limpas=limparApoliceObs(obs);const marcForma=`${APOLICE_FORMA_MARK}${forma}]`;if(forma==='avista')return [limpas,marcForma].filter(Boolean).join('\n');const n=(vencs||[]).length;const marcParc=`${APOLICE_PARC_MARK}${n}]`;const datas=(vencs||[]).map(x=>String(x||'').trim()).filter(Boolean);const marcVenc=datas.length?`${APOLICE_VENC_MARK}${datas.join(',')}]`:'';const marcDiv=`${APOLICE_DIVIDIR_MARK}${dividir?'sim':'nao'}]`;const marcVals=!dividir&&valores?.length?`${APOLICE_VALS_MARK}${valores.map(v=>parseMoney(v).toFixed(2)).join(',')}]`:'';return [limpas,marcForma,marcParc,marcVenc,marcDiv,marcVals].filter(Boolean).join('\n')}
function apoliceParcelaPagamentoKey(i){return `apolice_parcela_${i+1}`}
function valorApoliceParcelaPagamento(fin={},index=0){const qtd=fin.forma_pagamento_apolice==='parcelado'?Math.max(2,Number(fin.numero_parcelas_apolice||2)):1;if(fin.forma_pagamento_apolice!=='parcelado')return fin.seguro_premio;if(fin.dividir_valor_apolice!==false)return qtd?parseMoney(fin.seguro_premio)/qtd:0;return fin.valores_apolice?.[index]}
function ordinalParcela(i){const nomes=['1º','2º','3º','4º','5º','6º','7º','8º','9º','10º','11º','12º'];return nomes[i-1]||`${i}º`}
function safeFileName(name=''){return String(name||'arquivo').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9._-]/g,'_')}
function comprovantePagamentoNome(p={}){return p.comprovante_nome||p.comprovante||p.nome||''}
function comprovantePagamentoDoc(p={}){return {id:p.comprovante_documento_id||p.documento_id||p.id||null,nome:comprovantePagamentoNome(p),storage_bucket:p.comprovante_bucket||p.comprovante_storage_bucket||p.storage_bucket||'documentos',storage_path:p.comprovante_path||p.comprovante_storage_path||p.storage_path||''}}
function comprovanteMetaPagamento(p={}){const nome=comprovantePagamentoNome(p);if(!nome)return {};const doc=comprovantePagamentoDoc(p);return {comprovante:nome,comprovante_nome:nome,comprovante_bucket:doc.storage_bucket||'documentos',comprovante_path:doc.storage_path||'',comprovante_documento_id:doc.id||null,comprovante_mime_type:p.comprovante_mime_type||p.mime_type||'',comprovante_tamanho_bytes:p.comprovante_tamanho_bytes||p.tamanho_bytes||0}}
function removerComprovanteMetaPagamento(p={}){const limpo={...p};['comprovante','comprovante_nome','comprovante_bucket','comprovante_path','comprovante_documento_id','comprovante_mime_type','comprovante_tamanho_bytes','comprovante_storage_bucket','comprovante_storage_path','documento_id','storage_bucket','storage_path','nome','mime_type','tamanho_bytes'].forEach(k=>delete limpo[k]);return limpo}
function emitirAcaoComprovantePagamento(acao,campo){if(typeof window==='undefined')return;window.dispatchEvent(new CustomEvent('jurisbpo:financeiro-comprovante',{detail:{acao,campo}}))}
function ComprovantePagamentoActions({pagamento={},field,canRemove=false}){const nome=comprovantePagamentoNome(pagamento);if(!nome)return null;return <span style={{display:'inline-flex',alignItems:'center',gap:5,flexWrap:'wrap'}}><span> · Comprovante: {nome}</span><button type="button" title="Visualizar comprovante" onClick={()=>emitirAcaoComprovantePagamento('visualizar',field)} style={{border:0,background:C.grayBg,color:C.text,borderRadius:6,padding:4,cursor:'pointer',display:'inline-flex'}}><Eye size={12}/></button>{canRemove&&<button type="button" title="Excluir comprovante" onClick={()=>emitirAcaoComprovantePagamento('excluir',field)} style={{border:0,background:C.redBg,color:C.red,borderRadius:6,padding:4,cursor:'pointer',display:'inline-flex'}}><Trash2 size={12}/></button>}</span>}
function F({label,children}){const texto=typeof label==='string'?label:'';const compacto=texto.length>22||texto.includes('/');return <div style={{marginBottom:12,flex:1}}><label style={{fontSize:compacto?10:11,lineHeight:compacto?1.05:1.15,fontWeight:800,color:C.muted,textTransform:'uppercase',display:'block',height:24,overflow:'hidden',marginBottom:5}}>{label}</label>{children}</div>}
function PaidValueField({label,field,fin,setFin,onPaid}){const pagamento=fin.pagamentos_campos?.[field]||{};const pago=pagamento?.pago;return <F label={label}><div style={{display:'flex',gap:6,alignItems:'center'}}><input type="text" inputMode="numeric" style={INP} value={moeda(fin[field])} onChange={e=>moedaChange(e.target.value,v=>setFin(f=>({...f,[field]:v})))} placeholder="R$ 0,00"/><button type="button" onClick={()=>onPaid(field,label)} style={{whiteSpace:'nowrap',border:'1px solid '+(pago?C.green:C.border),background:pago?C.greenBg:C.soft,color:pago?C.green:C.text,borderRadius:8,padding:'9px 10px',fontSize:12,fontWeight:800,cursor:'pointer',flexShrink:0}}>{pago?'Pago':'Marcar pago'}</button></div>{pago&&<div style={{fontSize:11,color:C.green,marginTop:4}}>Pago<ComprovantePagamentoActions pagamento={pagamento} field={field} canRemove={!!fin.id}/></div>}</F>}
function parcelaPagamentoKey(i){return `parcela_${i+1}`}
function labelPagamentoCampo(campo,fin={}){const fixos={valor_bruto:String(fin?.natureza||'').toLowerCase()==='execucao'?'Valor bruto / total da execução':'Valor bruto / total do acordo'};const campoFixo=fixos[campo];if(campoFixo)return campoFixo;const campoAP=CAMPOS_AP.find(([k])=>k===campo)?.[1];if(campoAP)return campoAP;const parcela=String(campo||'').match(/^parcela_(\d+)$/);if(parcela)return `Valor do ${ordinalParcela(Number(parcela[1]))} vencimento`;const apoliceParc=String(campo||'').match(/^apolice_parcela_(\d+)$/);if(apoliceParc)return `Prêmio apólice — ${ordinalParcela(Number(apoliceParc[1]))} vencimento`;return campo||'Pagamento'}
function valorParcelaPagamento(fin={},index=0){const qtd=fin.forma_pagamento==='parcelado'?Math.max(2,Number(fin.numero_parcelas||2)):1;if(fin.forma_pagamento!=='parcelado')return fin.valor_bruto;if(fin.dividir_valor_parcelas!==false)return qtd?parseMoney(fin.valor_bruto)/qtd:0;return fin.valores_parcelas?.[index]}
function PaidParcelValueField({label,index,fin,setFin,onPaid}){const field=parcelaPagamentoKey(index);const pagamento=fin.pagamentos_campos?.[field]||{};const pago=pagamento?.pago;return <F label={label}><div style={{display:'flex',gap:6,alignItems:'center'}}><input type="text" inputMode="numeric" style={{...INP,minWidth:0,flex:1}} value={moeda(valorParcelaPagamento(fin,index))} onChange={e=>moedaChange(e.target.value,v=>setFin(f=>{if(f.forma_pagamento!=='parcelado')return {...f,valor_bruto:v,valores_parcelas:[v]};const arr=Array.from({length:Math.max(2,Number(f.numero_parcelas||2))},(_,j)=>f.valores_parcelas?.[j]||'');arr[index]=v;return {...f,dividir_valor_parcelas:false,valores_parcelas:arr}}))} placeholder="R$ 0,00"/><button type="button" onClick={()=>onPaid(field,label)} style={{whiteSpace:'nowrap',border:'1px solid '+(pago?C.green:C.border),background:pago?C.greenBg:C.soft,color:pago?C.green:C.text,borderRadius:8,padding:'9px 10px',fontSize:12,fontWeight:800,cursor:'pointer',flexShrink:0}}>{pago?'Pago':'Marcar pago'}</button></div>{pago&&<div style={{fontSize:11,color:C.green,marginTop:4}}>Pago<ComprovantePagamentoActions pagamento={pagamento} field={field} canRemove={!!fin.id}/></div>}</F>}
function PaidParcelApoliceValueField({label,index,fin,setFin,onPaid}){const field=apoliceParcelaPagamentoKey(index);const pagamento=fin.pagamentos_campos?.[field]||{};const pago=pagamento?.pago;return <F label={label}><div style={{display:'flex',gap:6,alignItems:'center'}}><input type="text" inputMode="numeric" style={{...INP,minWidth:0,flex:1}} value={moeda(valorApoliceParcelaPagamento(fin,index))} onChange={e=>moedaChange(e.target.value,v=>setFin(f=>{if(f.forma_pagamento_apolice!=='parcelado')return {...f,seguro_premio:v,valores_apolice:[v]};const arr=Array.from({length:Math.max(2,Number(f.numero_parcelas_apolice||2))},(_,j)=>f.valores_apolice?.[j]||'');arr[index]=v;return {...f,dividir_valor_apolice:false,valores_apolice:arr}}))} placeholder="R$ 0,00"/><button type="button" onClick={()=>onPaid(field,label)} style={{whiteSpace:'nowrap',border:'1px solid '+(pago?C.green:C.border),background:pago?C.greenBg:C.soft,color:pago?C.green:C.text,borderRadius:8,padding:'9px 10px',fontSize:12,fontWeight:800,cursor:'pointer',flexShrink:0}}>{pago?'Pago':'Marcar pago'}</button></div>{pago&&<div style={{fontSize:11,color:C.green,marginTop:4}}>Pago<ComprovantePagamentoActions pagamento={pagamento} field={field} canRemove={!!fin.id}/></div>}</F>}
function Modal({title,onClose,children}){return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&(e.currentTarget._md=1)} onClick={e=>e.target===e.currentTarget&&e.currentTarget._md&&(delete e.currentTarget._md,onClose())} style={{position:'fixed',inset:0,background:'rgba(0,0,0,.45)',zIndex:500,display:'flex',alignItems:'center',justifyContent:'center',padding:16}}><div className="modal-content" style={{background:C.white,borderRadius:14,width:'100%',maxWidth:1080,maxHeight:'92vh',display:'flex',flexDirection:'column',overflow:'hidden'}}><div className="modal-header" style={{display:'flex',justifyContent:'space-between',padding:18,borderBottom:'1px solid '+C.border}}><b>{title}</b><button onClick={onClose} style={{border:0,background:'none',cursor:'pointer'}}><X/></button></div><div className="modal-body" style={{padding:18,overflow:'auto'}}>{children}</div></div></div>}

const AP_INPUT={width:'100%',border:'1px solid #111',minHeight:26,padding:'4px 6px',fontSize:12,boxSizing:'border-box',background:'#fff'}
const AP_DEPARTAMENTOS=['BRASÍLIA','SÃO PAULO','PAULÍNIA','RORAIMA','RIO DE JANEIRO','BAHIA','AMAZONAS','VALPARAÍSO DO GOIÁS','RONDÔNIA','ALAGOAS','TERESINA']
