function financeiroQuitado(f){
  return ['pago','quitado','concluido','concluído'].includes(String(f.status_pagamento||'').toLowerCase())
}
function economiaPodeSerContabilizada(proc, financeiros=[]){
  return proc?.transito_julgado===true || financeiros.some(f=>['acordo','execucao','execução'].includes(String(f.natureza||'').toLowerCase()) && financeiroQuitado(f))
}
function resumoFinanceiroProcesso(proc, financeiros=[]){
  const totalGasto=financeiros.reduce((s,f)=>s+totalFinanceiroRegistro(f),0)
  const valorAcao=Number(proc?.valor_acao||0)
  const elegivel=economiaPodeSerContabilizada(proc,financeiros)
  return {totalGasto,elegivel,valorEconomizado:elegivel?Math.max(valorAcao-totalGasto,0):0}
}

const emptyFinance={natureza:'acordo',data_referencia:'',valor_bruto:'',deposito_ro:'',deposito_rr:'',deposito_embargos:'',agravo_instrumento:'',valor_restituido:'',origem_restituicao:[],forma_pagamento:'avista',numero_parcelas:1,atualizar_selic:false,primeiro_vencimento:'',custas:'',fgts:'',honorarios_sucumbenciais:'',honorarios_periciais:'',honorarios_e_custos:'',inss_reclamante:'',inss_reclamada:'',multa_inadimplemento:'',status_pagamento:'pendente',pagamentos_campos:{},auditoria_pagamentos:[],seguro_garantia:false,apolice_numero:'',apolice_inicio:'',apolice_fim:'',valor_assegurado:'',seguro_premio:'',observacoes:'',vencimentos_parcelas:[''],dividir_valor_parcelas:true,valores_parcelas:[''],forma_pagamento_apolice:'avista',numero_parcelas_apolice:1,vencimentos_apolice:[''],valores_apolice:[''],dividir_valor_apolice:true}

function parseCSV(text){
  const lines=text.split(/\r?\n/).filter(Boolean)
  if(!lines.length)return[]
  const headers=lines[0].split(',').map(h=>h.replace(/^\uFEFF/,'').trim().replace(/^"|"$/g,''))
  return lines.slice(1).map(line=>{
    const cols=[];let cur='',inQ=false
    for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'&&!inQ)inQ=true;else if(ch==='"'&&inQ&&line[i+1]==='"'){cur+='"';i++}else if(ch==='"'&&inQ)inQ=false;else if(ch===','&&!inQ){cols.push(cur);cur=''}else cur+=ch}
    cols.push(cur)
    return Object.fromEntries(headers.map((h,i)=>[h,(cols[i]||'').trim()]))
  }).filter(r=>r.titulo&&r.titulo!=='titulo')
}

function gerarNumeroControle(){const c='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';let r='CTL-';for(let i=0;i<8;i++)r+=c[Math.floor(Math.random()*c.length)];return r}

