        <F label="Acordo realizado"><select style={INP} value={adv.acordo} onChange={e=>setAdv({...adv,acordo:e.target.value})}>{[['todos','Todos'],['sim','Sim'],['nao','Não']].map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></F>
