    {(q.trim()||Object.entries(adv).some(([k,v])=>k==='numero_controle'?!!v:v!=='todos'))&&<section style={{marginBottom:18}}><h3 style={{fontSize:14,margin:'0 0 8px'}}>Resultados da busca</h3><div style={{background:C.white,border:'1px solid '+C.border,borderRadius:12,overflow:'hidden'}}>{list.slice(0,20).map(p=><button key={p.id} onClick={()=>open(p)} style={{width:'100%',textAlign:'left',display:'block',background:'none',border:'none',borderBottom:'1px solid '+C.border,padding:14,cursor:'pointer',transition:'background .1s',color:C.text}} onMouseEnter={e=>e.currentTarget.style.background=C.grayBg} onMouseLeave={e=>e.currentTarget.style.background='none'}><div style={{display:'flex',gap:8,alignItems:'center',flexWrap:'wrap',marginBottom:2}}><span className="prv" style={{fontFamily:'monospace',fontSize:12,color:C.muted}}>{p.numero||'sem número'}</span>{p.numero_controle&&<span style={{fontFamily:'monospace',fontSize:10,background:'#0f172a',color:'#f0f9ff',padding:'2px 8px',borderRadius:10,fontWeight:800,letterSpacing:'0.04em',flexShrink:0}}>{p.numero_controle}</span>}</div><b className="prv" style={{display:'block',color:C.text,fontWeight:800,fontSize:14}}>{p.titulo}</b><div style={{fontSize:12,color:C.muted,marginTop:3}}>{p.tribunal||p.orgao||'—'} · {label(CATEGORIAS,p.categoria||'trabalhista')} · {label(STATUS,p.status)} · {label(FASES,p.fase)}</div></button>)}{!list.length&&<div style={{padding:30,textAlign:'center',color:C.muted}}>Nenhum processo encontrado.</div>}</div></section>}
